```python
def count_elements(numbers):
    result = {}
    for num in numbers:
        if isinstance(num, tuple):
            for elem in num:
                if elem in result:
                    result[elem] += 1
                else:
                    result[elem] = 1
        elif num in result:
            result[num] += 1
        else:
            result[num] = 1
    return result
```

